            totp: 'TOTP',
            totpText: 'TOTP („Time-based One-Time Password") ist der Code aus einer Authenticator-App. Stellen: Länge des Codes (4–8, Standard 6). Periode: Gültigkeitsdauer eines Codes in Sekunden (15–60, Standard 30). Hash-Algorithmus: SHA1 (mit allen Apps kompatibel), SHA256 oder SHA512. Drift-Fenster: wie viele Perioden vor/nach jetzt akzeptiert werden (0–3, 1 ist üblich). Aussteller: Name in der Authenticator-App. Ändere diese Werte nicht im laufenden Betrieb - bereits eingerichtete Apps liefern sonst ungültige Codes.',
            backupCodes: 'Backup-Codes',
            backupCodesText: 'Backup-Codes sind einmal verwendbare Wiederherstellungscodes für den Fall, dass der primäre Faktor nicht verfügbar ist. Anzahl: wie viele Codes pro Einrichtung erzeugt werden (5–20, Standard 10). Mehr als 20 verleiten Nutzer dazu, sie unsicher zu speichern.',
