            pageText2: 'Im Bereich "Inhalt" werden die Behälter, die direkt in diesem liegen, und die Items, die diesem Behälter zugeordnet sind, aufgelistet. Mit dem Schalter "Verschachtelt anzeigen" bekommst du zusätzlich alle Items aus untergeordneten Behältern eingeblendet.',
